window.KH_SURA(31, {"sura": "لقمان", "n": 31, "ayat": {"1": "الم", "2": "تِلْكَ آيَاتُ الْكِتَابِ الْحَكِيمِ", "3": "هُدًى وَرَحْمَةً لِلْمُحْسِنِينَ", "4": "الَّذِينَ يُقِيمُونَ الصَّلَاةَ وَيُؤْتُونَ الزَّكَاةَ وَهُمْ بِالْآخِرَةِ هُمْ يُوقِنُونَ", "5": "أُولَئِكَ عَلَى هُدًى مِنْ رَبِّهِمْ وَأُولَئِكَ هُمُ الْمُفْلِحُونَ", "6": "وَمِنَ النَّاسِ مَنْ يَشْتَرِي لَهْوَ الْحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ بِغَيْرِ عِلْمٍ وَيَتَّخِذَهَا هُزُوًا أُولَئِكَ لَهُمْ عَذَابٌ مُهِينٌ", "7": "وَإِذَا تُتْلَى عَلَيْهِ آيَاتُنَا وَلَّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْهَا كَأَنَّ فِي أُذُنَيْهِ وَقْرًا فَبَشِّرْهُ بِعَذَابٍ أَلِيمٍ", "8": "إِنَّ الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ لَهُمْ جَنَّاتُ النَّعِيمِ", "9": "خَالِدِينَ فِيهَا وَعْدَ اللَّهِ حَقًّا وَهُوَ الْعَزِيزُ الْحَكِيمُ", "10": "خَلَقَ السَّمَاوَاتِ بِغَيْرِ عَمَدٍ تَرَوْنَهَا وَأَلْقَى فِي الْأَرْضِ رَوَاسِيَ أَنْ تَمِيدَ بِكُمْ وَبَثَّ فِيهَا مِنْ كُلِّ دَابَّةٍ وَأَنْزَلْنَا مِنَ السَّمَاءِ مَاءً فَأَنْبَتْنَا فِيهَا مِنْ كُلِّ زَوْجٍ كَرِيمٍ", "11": "هَذَا خَلْقُ اللَّهِ فَأَرُونِي مَاذَا خَلَقَ الَّذِينَ مِنْ دُونِهِ بَلِ الظَّالِمُونَ فِي ضَلَالٍ مُبِينٍ", "12": "وَلَقَدْ آتَيْنَا لُقْمَانَ الْحِكْمَةَ أَنِ اشْكُرْ لِلَّهِ وَمَنْ يَشْكُرْ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِ وَمَنْ كَفَرَ فَإِنَّ اللَّهَ غَنِيٌّ حَمِيدٌ", "13": "وَإِذْ قَالَ لُقْمَانُ لِابْنِهِ وَهُوَ يَعِظُهُ يَابُنَيَّ لَا تُشْرِكْ بِاللَّهِ إِنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ", "14": "وَوَصَّيْنَا الْإِنْسَانَ بِوَالِدَيْهِ حَمَلَتْهُ أُمُّهُ وَهْنًا عَلَى وَهْنٍ وَفِصَالُهُ فِي عَامَيْنِ أَنِ اشْكُرْ لِي وَلِوَالِدَيْكَ إِلَيَّ الْمَصِيرُ", "15": "وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلَا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا وَاتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَيَّ ثُمَّ إِلَيَّ مَرْجِعُكُمْ فَأُنَبِّئُكُمْ بِمَا كُنْتُمْ تَعْمَلُونَ", "16": "يَابُنَيَّ إِنَّهَا إِنْ تَكُ مِثْقَالَ حَبَّةٍ مِنْ خَرْدَلٍ فَتَكُنْ فِي صَخْرَةٍ أَوْ فِي السَّمَاوَاتِ أَوْ فِي الْأَرْضِ يَأْتِ بِهَا اللَّهُ إِنَّ اللَّهَ لَطِيفٌ خَبِيرٌ", "17": "يَابُنَيَّ أَقِمِ الصَّلَاةَ وَأْمُرْ بِالْمَعْرُوفِ وَانْهَ عَنِ الْمُنْكَرِ وَاصْبِرْ عَلَى مَا أَصَابَكَ إِنَّ ذَلِكَ مِنْ عَزْمِ الْأُمُورِ", "18": "وَلَا تُصَعِّرْ خَدَّكَ لِلنَّاسِ وَلَا تَمْشِ فِي الْأَرْضِ مَرَحًا إِنَّ اللَّهَ لَا يُحِبُّ كُلَّ مُخْتَالٍ فَخُورٍ", "19": "وَاقْصِدْ فِي مَشْيِكَ وَاغْضُضْ مِنْ صَوْتِكَ إِنَّ أَنْكَرَ الْأَصْوَاتِ لَصَوْتُ الْحَمِيرِ", "20": "أَلَمْ تَرَوْا أَنَّ اللَّهَ سَخَّرَ لَكُمْ مَا فِي السَّمَاوَاتِ وَمَا فِي الْأَرْضِ وَأَسْبَغَ عَلَيْكُمْ نِعَمَهُ ظَاهِرَةً وَبَاطِنَةً وَمِنَ النَّاسِ مَنْ يُجَادِلُ فِي اللَّهِ بِغَيْرِ عِلْمٍ وَلَا هُدًى وَلَا كِتَابٍ مُنِيرٍ", "21": "وَإِذَا قِيلَ لَهُمُ اتَّبِعُوا مَا أَنْزَلَ اللَّهُ قَالُوا بَلْ نَتَّبِعُ مَا وَجَدْنَا عَلَيْهِ آبَاءَنَا أَوَلَوْ كَانَ الشَّيْطَانُ يَدْعُوهُمْ إِلَى عَذَابِ السَّعِيرِ", "22": "وَمَنْ يُسْلِمْ وَجْهَهُ إِلَى اللَّهِ وَهُوَ مُحْسِنٌ فَقَدِ اسْتَمْسَكَ بِالْعُرْوَةِ الْوُثْقَى وَإِلَى اللَّهِ عَاقِبَةُ الْأُمُورِ", "23": "وَمَنْ كَفَرَ فَلَا يَحْزُنْكَ كُفْرُهُ إِلَيْنَا مَرْجِعُهُمْ فَنُنَبِّئُهُمْ بِمَا عَمِلُوا إِنَّ اللَّهَ عَلِيمٌ بِذَاتِ الصُّدُورِ", "24": "نُمَتِّعُهُمْ قَلِيلًا ثُمَّ نَضْطَرُّهُمْ إِلَى عَذَابٍ غَلِيظٍ", "25": "وَلَئِنْ سَأَلْتَهُمْ مَنْ خَلَقَ السَّمَاوَاتِ وَالْأَرْضَ لَيَقُولُنَّ اللَّهُ قُلِ الْحَمْدُ لِلَّهِ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ", "26": "لِلَّهِ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ إِنَّ اللَّهَ هُوَ الْغَنِيُّ الْحَمِيدُ", "27": "وَلَوْ أَنَّمَا فِي الْأَرْضِ مِنْ شَجَرَةٍ أَقْلَامٌ وَالْبَحْرُ يَمُدُّهُ مِنْ بَعْدِهِ سَبْعَةُ أَبْحُرٍ مَا نَفِدَتْ كَلِمَاتُ اللَّهِ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ", "28": "مَا خَلْقُكُمْ وَلَا بَعْثُكُمْ إِلَّا كَنَفْسٍ وَاحِدَةٍ إِنَّ اللَّهَ سَمِيعٌ بَصِيرٌ", "29": "أَلَمْ تَرَ أَنَّ اللَّهَ يُولِجُ اللَّيْلَ فِي النَّهَارِ وَيُولِجُ النَّهَارَ فِي اللَّيْلِ وَسَخَّرَ الشَّمْسَ وَالْقَمَرَ كُلٌّ يَجْرِي إِلَى أَجَلٍ مُسَمًّى وَأَنَّ اللَّهَ بِمَا تَعْمَلُونَ خَبِيرٌ", "30": "ذَلِكَ بِأَنَّ اللَّهَ هُوَ الْحَقُّ وَأَنَّ مَا يَدْعُونَ مِنْ دُونِهِ الْبَاطِلُ وَأَنَّ اللَّهَ هُوَ الْعَلِيُّ الْكَبِيرُ", "31": "أَلَمْ تَرَ أَنَّ الْفُلْكَ تَجْرِي فِي الْبَحْرِ بِنِعْمَتِ اللَّهِ لِيُرِيَكُمْ مِنْ آيَاتِهِ إِنَّ فِي ذَلِكَ لَآيَاتٍ لِكُلِّ صَبَّارٍ شَكُورٍ", "32": "وَإِذَا غَشِيَهُمْ مَوْجٌ كَالظُّلَلِ دَعَوُا اللَّهَ مُخْلِصِينَ لَهُ الدِّينَ فَلَمَّا نَجَّاهُمْ إِلَى الْبَرِّ فَمِنْهُمْ مُقْتَصِدٌ وَمَا يَجْحَدُ بِآيَاتِنَا إِلَّا كُلُّ خَتَّارٍ كَفُورٍ", "33": "يَاأَيُّهَا النَّاسُ اتَّقُوا رَبَّكُمْ وَاخْشَوْا يَوْمًا لَا يَجْزِي وَالِدٌ عَنْ وَلَدِهِ وَلَا مَوْلُودٌ هُوَ جَازٍ عَنْ وَالِدِهِ شَيْئًا إِنَّ وَعْدَ اللَّهِ حَقٌّ فَلَا تَغُرَّنَّكُمُ الْحَيَاةُ الدُّنْيَا وَلَا يَغُرَّنَّكُمْ بِاللَّهِ الْغَرُورُ", "34": "إِنَّ اللَّهَ عِنْدَهُ عِلْمُ السَّاعَةِ وَيُنَزِّلُ الْغَيْثَ وَيَعْلَمُ مَا فِي الْأَرْحَامِ وَمَا تَدْرِي نَفْسٌ مَاذَا تَكْسِبُ غَدًا وَمَا تَدْرِي نَفْسٌ بِأَيِّ أَرْضٍ تَمُوتُ إِنَّ اللَّهَ عَلِيمٌ خَبِيرٌ"}, "units": [{"aya": 6, "title": "في تأويل قوله: ﴿ومن الناس من يشتري لهو الحديث﴾", "tabari": {"page": "18/532", "sarih": 1, "tarjih": "والصواب من القول في ذلك أن يقال: عنى به كل ما كان من الحديث ملهيا عن سبيل الله، مما نهى الله عن استماعه أو رسوله؛ لأن الله تعالى ذكره عم بقوله: ﴿لهو الحديث﴾، ولم يخصص بعضا دون بعض، فذلك على عمومه، حتى يأتي ما يدل على خصوصه، والغناء والشرك من ذلك.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "من يشترى الشراء المعروف بالثمن، ورووا بذلك خبرا عن رسول الله ﷺ، وهو ما حدثنا أبو كريب، قال: ثنا وكيع، عن خلاد الصفار، عن عبيد الله بن زحر، عن علي بن يزيد، عن القاسم، عن أبي أمامة، قال: قال رسول الله ﷺ: \"لا يحل بيع المغنيات، ولا شراؤهن، ولا التجارة فيهن، ولا أثمانهن، وفيهن نزلت هذه الآية: ﴿ومن الناس من يشتري لهو الحديث﴾ \"", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "بل معنى ذلك: من يختار لهو الحديث ويستحبه", "taqdim": 0, "n_athar": 24, "qailun": [["قتادة", "تابعي"], ["مطر", ""], ["أبي الصهباء البكري", "تابعي"], ["أبي الصهباء", ""], ["ابن عباس", "صحابي"], ["جابر", "صحابي"], ["مجاهد", "تابعي"], ["عكرمة", "تابعي"], ["شعيب بن يسار", ""]], "athar": [60837, 60838, 60839, 60849, 60850, 60851, 60852, 60853, 60854, 60855, 60856, 60858, 60859, 60860, 60861, 60862, 60865, 60872, 60873, 60875, 60881, 60882, 60883, 60884, 60890]}, {"n": 3, "t": "عنى باللهو الطبل", "taqdim": 0, "n_athar": 1, "qailun": [["مجاهد", "تابعي"]], "athar": [60858, 60859, 60860, 60861, 60862, 60882]}, {"n": 4, "t": "عنى بلهو الحديث الشرك", "taqdim": 0, "n_athar": 2, "qailun": [["ابن زيد", "تابع التابعين"]], "athar": [60879]}]}, "mawaqif": [], "mushid": {"i": 1, "imgs": ["031_001_1.png"], "pages": [412], "n": 2, "rajih": [1], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 6, "title": "معنى الشراء", "mawsua": {"taliq": 5128, "masala": "معنى الشراء", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن الشراء بمعنى: الاستحباب", "ashab": "", "athar": []}, {"n": 2, "t": "أنه شراء على حقيقته", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5128, "mi": 1, "aya": 6, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 534", "qawl": "الثاني", "nass": "وأولى التأويلين عندي بالصواب تأويل من قال: معناه: الشراء، الذي هو بالثمن، وذلك أن ذلك هو أظهر معنييه", "qawaid": ["ظاهر الآية ولفظها"], "tabi": ""}], "tags": {"m": {"2": [["ابن جرير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["ظاهر الآية ولفظها"]}, "rulesD": {}}}, {"aya": 6, "title": "معنى اللهو", "mawsua": {"taliq": 5129, "masala": "معنى اللهو", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الغناء", "ashab": "", "athar": []}, {"n": 2, "t": "أنه الطبل", "ashab": "", "athar": []}, {"n": 3, "t": "أنه الشرك", "ashab": "", "athar": []}, {"n": 4, "t": "أنه أخبار الأعاجم وملوكها وملوك الروم", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5129, "mi": 1, "aya": 6, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 539", "qawl": "", "nass": "والصواب من القول في ذلك أن يقال: عنى به كل ما كان من الحديث ملهيا عن سبيل الله، مما نهى الله عن استماعه أو رسوله؛ لأن الله تعالى عم بقوله: {لهو الحديث} ولم يخصص بعضا دون بعض، فذلك على عمومه، حتى يأتي ما يدل على خصوصه، والغناء والشرك من ذلك", "qawaid": [], "tabi": ""}, {"taliq": 5129, "mi": 1, "aya": 6, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 42", "qawl": "", "nass": "والذي يترجح أن الآية نزلت في لهو حديث مضاف إلى كفر، فلذلك اشتدت ألفاظ الآية بقوله: {ليضل عن سبيل الله بغير علم ويتخذها هزوا}، وبالتوعد بالعذاب المهين، وأما لفظة الشراء فمحتملة للحقيقة والمجاز على ما بينا، ولهو الحديث: كل ما يلهي من غناء وخنا ونحوه", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 5129, "mi": 1, "aya": 6, "alam": "ابن القيم", "fil": "علق", "kind": "تعليق", "ref": "2/ 317 - 318", "qawl": "الأول", "nass": "ولا تعارض بين تفسير {لهو الحديث} بالغناء، وتفسيره: بأخبار الأعاجم وملوكها وملوك الروم، ونحو ذلك مما كان النضر بن الحارث يحدث به أهل مكة، يشغلهم به عن القرآن، فكلاهما لهو الحديث، ولهذا قال ابن عباس: لهو الحديث: الباطل والغناء. فمن الصحابة من ذكر هذا، ومنهم من ذكر الآخر، ومنهم من جمعهما", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن جرير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {}, "rulesD": {}}}, {"aya": 6, "title": "عود الهاء من قوله: {ويتخذها}", "mawsua": {"taliq": 5131, "masala": "عود الهاء من قوله: {ويتخذها}", "sigha": "ذكر قولين", "nasib": "ابن جرير", "aqwal": [{"n": 1, "t": "أنها تعود على سبيل الله. كما في قول مجاهد", "ashab": "", "athar": []}, {"n": 2, "t": "أنها من ذكر آيات الكتاب", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5131, "mi": 1, "aya": 6, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "18/ 541", "qawl": "مجاهد", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5131, "mi": 1, "aya": 6, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "", "qawl": "الأول", "nass": "{ويتخذها هزوا} يستهزئ بها ويكذب بها. وهما من أن يكونا من ذكر سبيل الله أشبه عندي لقربهما منها، وإن كان القول الآخر غير بعيد من الصواب. واتخاذه ذلك هزوا: هو استهزاؤه به", "qawaid": ["السياق"], "tabi": ""}, {"taliq": 5131, "mi": 1, "aya": 6, "alam": "ابن كثير", "fil": "وبنحوه", "kind": "موافقة", "ref": "11/ 47", "qawl": "", "nass": "", "qawaid": ["لم يذكر مستندًا"], "tabi": "ابن جرير"}, {"taliq": 5131, "mi": 1, "aya": 6, "alam": "ابن عطية", "fil": "زاد", "kind": "نقل", "ref": "7/ 42", "qawl": "", "nass": "ويحتمل أن يعود على الأحاديث؛ لأن الحديث اسم جنس بمعنى الأحاديث، وكذلك {سبيل الله} اسم جنس، ولكل وجه من الحديث وجه يليق به من السبيل", "qawaid": [], "tabi": ""}], "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["السياق"], "ابن كثير": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 12, "title": "تأويل: ﴿ولقد آتينا لقمان الحكمة أن اشكر لله ومن يشكر فإنما يشكر لنفسه ومن كفر فإن الله غني حميد﴾", "tabari": {"page": "18/549", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ولقد آتينا لقمان الفقه في الدين، والعقل، والإصابة في القول.", "taqdim": 1, "n_athar": 12, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["ابن عباس", "صحابي"], ["له سعيد", ""], ["خالد الربعي", ""], ["له", ""]], "athar": [60921, 60922, 60923, 60924, 60925, 60926, 60927, 60930, 60936, 60937, 60943, 60944, 60947, 60948]}, {"n": 2, "t": "كان نبيا", "taqdim": 0, "n_athar": 1, "qailun": [["عكرمة", "تابعي"]], "athar": []}]}, "mawaqif": [], "mushid": {"i": 4, "imgs": ["031_004_1.png"], "pages": [412], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 14, "title": "تأويل: ﴿ووصينا الإنسان بوالديه حملته أمه وهنا على وهن وفصاله في عامين أن اشكر لي ولوالديك إلي المص﴾", "tabari": {"page": "18/551", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: وأمرنا الإنسان ببر والديه، ﴿حملته أمه وهنا على وهن﴾. يقول: ضعفا على ضعف، وشدة على شدة. ومنه قول زهير :", "taqdim": 1, "n_athar": 3, "qailun": [["ابن عباس", "صحابي"], ["قتادة", "تابعي"]], "athar": [60963, 60969]}, {"n": 2, "t": "بل عنى بذلك وهن الولد وضعفه على وهن الأم", "taqdim": 0, "n_athar": 1, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 5, "imgs": ["031_005_1.png"], "pages": [413], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 14, "title": "تأويل: ﴿وفصاله في عامين﴾", "tabari": {"page": "18/551", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "﴿وفصاله في عامين﴾. يقول: وفطامه في انقضاء عامين.", "taqdim": 1, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "﴿وفصاله في عامين﴾. وترك ذكر \"انقضاء\"؛ اكتفاء بدلالة الكلام عليه، كما قيل: ﴿واسأل القرية التي كنا فيها﴾ [يوسف: ٨٢]، يراد به: أهل القرية", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 16, "title": "في معنى الهاء والألف اللتين في قوله: ﴿إنها﴾", "tabari": {"page": "18/554", "sarih": 1, "tarjih": "وأولى القولين بالصواب عندى القول الثاني؛ لأن الله تعالى ذكره لم يعد عباده أن يوفيهم جزاء سيئاتهم دون جزاء حسناتهم، فيقال: إن المعصية إن تك مثقال حبة من خردل يأت بها الله. بل وعد كلا العاملين أن يوفيه جزاء أعمالهما. فإذا كان ذلك كذلك كانت الهاء في قوله: ﴿إنها﴾ بأن تكون عمادا أشبه منها بأن تكون كناية عن الخطيئة والمعصية. وأما النصب في \"المثقال\"، فعلى أن في ﴿تك﴾ مجهولا، والرفع فيه على أن الخبر مضمر، كأنه قيل: إن تك في موضع مثقال حبة. لأن النكرات تضمر أخبارها، ثم يترجم عن المكان الذي فيه مثقال الحبة.", "how": "صاغ الصواب بلفظه (عموم أو جمع أو قول مستقل)", "aqwal": [{"n": 1, "t": "ذلك كناية عن المعصية والخطيئة. ومعنى الكلام عنده: يا بني، إن المعصية إن تك مثقال حبة من خردل، أو: إن الخطيئة", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}, {"n": 2, "t": "هذه الهاء عماد. وقال: أنت ﴿تك﴾؛ لأنه يراد بها الحبة، فذهب بالتأنيث إليها، كما قال الشاعر :", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [60992, 61000, 61007]}]}, "mawaqif": [{"taliq": 5137, "mi": 0, "aya": 16, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "18/ 554 - 556", "qawl": "مقاتل", "nass": "وقال بعض نحويي الكوفة: وهذه الهاء عماد. وقال: أنث {تك} لأنه يراد بها الحبة، فذهب بالتأنيث إليها", "qawaid": ["الدلالة العقلية"], "tabi": ""}, {"taliq": 5137, "mi": 0, "aya": 16, "alam": "ابن كثير", "fil": "رجح", "kind": "ترجيح", "ref": "11/ 55", "qawl": "الأول", "nass": "والأول أولى", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [["ابن كثير", "رجّح ولم يتعيّن القول آليًّا"]], "rules": {"ابن كثير": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 16, "title": "في معنى قوله: ﴿فتكن في صخرة﴾", "tabari": {"page": "18/556", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "عنى بها الصخرة التي عليها الأرض. وذلك قول روى عن ابن عباس وغيره، وقالوا: هي صخرة خضراء", "taqdim": 0, "n_athar": 2, "qailun": [["عبد الله بن الحارث", ""]], "athar": [60998]}, {"n": 2, "t": "عنى بها الجبال. قالوا: ومعنى الكلام: فتكن في جبل", "taqdim": 0, "n_athar": 1, "qailun": [["قتادة", "تابعي"]], "athar": [60992, 61000, 61007]}]}, "mawaqif": [{"taliq": 5139, "mi": 0, "aya": 16, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "18/ 557", "qawl": "", "nass": "ولا أعرف", "qawaid": [], "tabi": ""}], "mushid": {"i": 6, "imgs": ["031_006_1.png"], "pages": [413], "n": 2, "rajih": [], "daif": [], "match": true}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 17, "title": "قوله: {إن ذلك من عزم الأمور}", "mawsua": {"taliq": 5142, "masala": "قوله: {إن ذلك من عزم الأمور}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أن معناه: ذلك من حزم الأمور", "ashab": "", "athar": []}, {"n": 2, "t": "أن معناه: ذلك مما عزمه الله وأمر به", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5142, "mi": 1, "aya": 17, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 51", "qawl": "الثاني", "nass": "", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}], "tags": {"m": {"2": [["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["لم يذكر مستندًا"]}, "rulesD": {}}}, {"aya": 18, "title": "في تأويله", "tabari": {"page": "18/559", "sarih": 1, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "إنما نهاه عن ذلك أن يفعله لمن بينه وبينه صعر، لا على وجه التكبر", "taqdim": 0, "n_athar": 2, "qailun": [["مجاهد", "تابعي"]], "athar": [61032, 61033, 61046]}, {"n": 2, "t": "هو التشديق", "taqdim": 0, "n_athar": 3, "qailun": [["إبراهيم", "تابعي"]], "athar": [61030]}]}, "mawaqif": [{"taliq": 5145, "mi": 0, "aya": 19, "alam": "ابن جرير", "fil": "جمع", "kind": "توجيه", "ref": "18/ 562", "qawl": "يزيد وقول", "nass": "قوله تعالى: {واقصد في مشيك} يقول: وتواضع في مشيك إذا مشيت، ولا تستكبر، ولا تستعجل، ولكن اتئد. وبنحو الذي قلنا في ذلك قال أهل التأويل، غير أن منهم من قال: أمره بالتواضع في مشيه. ومنهم من قال: أمره بترك السرعة فيه", "qawaid": [], "tabi": ""}], "mushid": {"i": 7, "imgs": ["031_007_1.png"], "pages": [413], "n": 3, "rajih": [1], "daif": [], "match": false}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 18, "title": "معنى: {ولا تصعر خدك}", "mawsua": {"taliq": 5143, "masala": "معنى: {ولا تصعر خدك}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنه الإعراض بالوجه تكبرا", "ashab": "", "athar": []}, {"n": 2, "t": "أنه التشديق", "ashab": "", "athar": []}, {"n": 3, "t": "أنه الإعراض عمن بينك وبينه خصومة وإحنة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5143, "mi": 1, "aya": 18, "alam": "ابن جرير", "fil": "رجح", "kind": "ترجيح", "ref": "18/ 559", "qawl": "الأول", "nass": "", "qawaid": ["اللغة"], "tabi": ""}, {"taliq": 5143, "mi": 1, "aya": 18, "alam": "ابن كثير", "fil": "وبنحوه", "kind": "موافقة", "ref": "6/ 339", "qawl": "", "nass": "", "qawaid": [], "tabi": "ابن جرير"}, {"taliq": 5143, "mi": 1, "aya": 18, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 52", "qawl": "", "nass": "ويحتمل أن يريد أيضا الضد، أي: ولا سؤالا ولا ضراعة بالفقر", "qawaid": ["السياق"], "tabi": ""}], "tags": {"m": {"1": [["ابن جرير", "r"], ["ابن كثير", "r"]]}, "t": {}, "gen": [], "rules": {"ابن جرير": ["اللغة"]}, "rulesD": {}}}, {"aya": 19, "title": "تأويل: ﴿إن الله لا يحب كل مختال﴾", "tabari": {"page": "18/563", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "أمره بالتواضع في مشيه", "taqdim": 0, "n_athar": 2, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"]], "athar": [61052, 61053, 61058, 61062, 61063, 61069]}, {"n": 2, "t": "نهاه عن السرعة", "taqdim": 0, "n_athar": 1, "qailun": [["يزيد بن أبى حبيب", "تابعي"]], "athar": [61054]}]}, "mawaqif": [], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 19, "title": "في تأويل قوله: ﴿إن أنكر الأصوات لصوت الحمير﴾", "tabari": {"page": "18/564", "sarih": 1, "tarjih": "وأولى الأقوال في ذلك بالصواب قول من قال: معناه: إن أقبح أو أشر الأصوات، وذلك نظير قولهم إذا رأوا وجها قبيحا أو منظرا شنيعا: ما أنكر وجه فلان، وما أنكر منظره!", "how": "رجّح قول فريق («قول من قال…»)", "aqwal": [{"n": 1, "t": "معناه: إن أقبح الأصوات", "taqdim": 0, "n_athar": 3, "qailun": [["شعبة وأبان بن تغلب", "تابع التابعين"], ["قتادة", "تابعي"]], "athar": [61053, 61058, 61069]}, {"n": 2, "t": "بل معنى ذلك: إن أشر الأصوات", "taqdim": 0, "n_athar": 2, "qailun": [["عكرمة والحكم ابن عتيبة", "تابعي"], ["ابن زيد", "تابع التابعين"]], "athar": [61060, 61076]}]}, "mawaqif": [{"taliq": 5146, "mi": 1, "aya": 19, "alam": "ابن جرير", "fil": "جمع", "kind": "توجيه", "ref": "18/ 565", "qawl": "", "nass": "وأولى الأقوال في ذلك بالصواب قول من قال: معناه: إن أقبح أو أشر الأصوات. وذلك نظير قولهم إذا رأوا وجها قبيحا أو منظرا شنيعا: ما أنكر وجه فلان، وما أنكر منظره", "qawaid": ["اللغة"], "tabi": ""}], "mushid": {"i": 8, "imgs": ["031_008_1.png"], "pages": [413], "n": 2, "rajih": [], "daif": [], "match": true}, "mawsua": {"taliq": 5146, "masala": "تفسير قوله: {إن أنكر الأصوات لصوت الحمير}", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أقبح", "ashab": "", "athar": []}, {"n": 2, "t": "أشر", "ashab": "", "athar": []}]}, "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 27, "title": "نزول قوله تعالى: {ولو أنما في الأرض من شجرة أقلام والبحر يمده من بعده سبعة أبحر} الآية", "mawsua": {"taliq": 5150, "masala": "نزول قوله تعالى: {ولو أنما في الأرض من شجرة أقلام والبحر يمده من بعده سبعة أبحر} الآية", "sigha": "خلاف مصرَّح به", "nasib": "", "aqwal": [{"n": 1, "t": "أنها نزلت بسبب سؤال سأله أحبار اليهود لرسول الله صلى الله عليه وسلم", "ashab": "", "athar": []}, {"n": 2, "t": "أنها نزلت بسبب أن المشركين قالوا في القرآن: إنما هو كلام يوشك أن ينفد وينقطع", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5150, "mi": 1, "aya": 27, "alam": "ابن عطية", "fil": "رجح", "kind": "ترجيح", "ref": "7/ 57", "qawl": "الأول", "nass": "وهذا هو القول الصحيح، والآية مدنية", "qawaid": ["سبب النزول وأحواله"], "tabi": ""}, {"taliq": 5150, "mi": 1, "aya": 27, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 78", "qawl": "الأول", "nass": "وهذا يقتضي أن هذه الآية مدنية لا مكية، والمشهور أنها مكية", "qawaid": [], "tabi": ""}], "tags": {"m": {"1": [["ابن عطية", "r"]]}, "t": {}, "gen": [], "rules": {"ابن عطية": ["سبب النزول وأحواله"]}, "rulesD": {}}}, {"aya": 29, "title": "قوله تعالى: {كل يجري إلى أجل مسمى}", "mawsua": {"taliq": 5152, "masala": "قوله تعالى: {كل يجري إلى أجل مسمى}", "sigha": "ذكر معنيين", "nasib": "ابن كثير", "aqwal": [{"n": 1, "t": "إلى غاية محدودة", "ashab": "", "athar": []}, {"n": 2, "t": "إلى يوم القيامة", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5152, "mi": 1, "aya": 29, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 79", "qawl": "", "nass": "وكلا المعنيين صحيح", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 30, "title": "معنى: {وأن ما تدعون}", "mawsua": {"taliq": 5153, "masala": "معنى: {وأن ما تدعون}", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد الأصنام، وتكون {ما} بمعنى: الذي، ويكون الإخبار عنها بالباطل", "ashab": "", "athar": []}, {"n": 2, "t": "أن تكون {ما} مصدرية، كأنه قال: وأن دعاءكم آلهة من دونه الباطل، أي: الفعل الذي لا يؤدي إلى الغاية المطلوبة به", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5153, "mi": 1, "aya": 30, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 60", "qawl": "", "nass": "أن يريد الأصنام، وتكون {ما} بمعنى: الذي، ويكون الإخبار عنها بالباطل", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 31, "title": "معنى الآية", "mawsua": {"taliq": 5154, "masala": "معنى الآية", "sigha": "ذكر احتمالين", "nasib": "ابن عطية", "aqwal": [{"n": 1, "t": "أن يريد: ما تحمله السفن من الطعام والأرزاق والتجارات، فالباء للأرزاق", "ashab": "", "athar": []}, {"n": 2, "t": "أن يريد: بالريح وتسخير الله تعالى البحر ونحو هذا", "ashab": "", "athar": []}]}, "mawaqif": [{"taliq": 5154, "mi": 1, "aya": 31, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 61", "qawl": "", "nass": "أن يريد: ما تحمله السفن من الطعام والأرزاق والتجارات، فالباء للأرزاق", "qawaid": [], "tabi": ""}], "tags": {"m": {}, "t": {}, "gen": [], "rules": {}, "rulesD": {}}}, {"aya": 34, "title": "تأويل: ﴿إن الله عنده علم الساعة وينزل الغيث ويعلم ما في الأرحام وما تدري نفس ماذا تكسب غدا وما تدر﴾", "tabari": {"page": "18/588", "sarih": 0, "tarjih": "", "how": "", "aqwal": [{"n": 1, "t": "يقول تعالى ذكره: ﴿ياأيها الناس اتقوا ربكم واخشوا يوما لا يجزي والد عن ولده ولا مولود هو جاز عن والده شيئا﴾ - هو آتيكم، علم إتيانه إياكم عند ربكم، لا يعلم أحد متى هو جائيكم، لا يأتيكم إلا بغتة، فاتقوه أن يفجأكم بغتة وأنتم على ضلالتكم لم تنيبوا منها، فتصيروا من عذاب الله وعقابه إلى ما لا قبل لكم به، وابتدأ تعالى ذكره الخبر عن علمه بمجيء الساعة - والمعنى ما ذكرت لدلالة الكلام على المراد منه - فقال: ﴿", "taqdim": 1, "n_athar": 10, "qailun": [["مجاهد", "تابعي"], ["قتادة", "تابعي"], ["الشعبي", "تابعي"], ["عمرو بن شعيب", "تابعي"], ["عبد الله بن عمر", "صحابي"], ["عبد الله بن دينار", "تابعي"], ["ابن عمر", "صحابي"], ["ابن مسعود", "صحابي"], ["عائشة", "صحابي"]], "athar": [61197, 61202, 61210, 61211, 61214, 61222]}, {"n": 2, "t": "﴿بأي أرض تموت﴾، وفيه لغة أخرى (بأية أرض) ، فمن قال: ﴿بأي أرض﴾ اجتزأ بتأنيث الأرض من أن يظهر في \"أي\" تأنيث آخر، ومن قال: (بأية أرض) فأنث \"أي\"، قال: قد تجتزيء ب \"أي\" مما أضيف إليه، فلابد من التأنيث؛ كقول القائل: مررت بامرأة. فيقال له: بأية؟ ومررت برجل. فيقال له: بأي؟ ويقال: أي امرأة جاءتك وجاءك؟ وأية امرأة جاءتك؟", "taqdim": 0, "n_athar": 0, "qailun": [], "athar": []}]}, "mawaqif": [], "mushid": {"i": 9, "imgs": ["031_009_1.png"], "pages": [413], "n": 2, "rajih": [1], "daif": [], "match": true}, "tags": {"m": {}, "t": {"1": [["ابن جرير", "r"]]}, "gen": [], "rules": {}, "rulesD": {}}}], "extra": [{"i": 2, "aya": 6, "imgs": ["031_002_1.png"], "pages": [412], "ihala": 0}, {"i": 3, "aya": 6, "imgs": ["031_003_1.png"], "pages": [412], "ihala": 0}], "others": {"0": [{"id": 5126, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 40): «و {الحَكِيمِ} يصح أن يكون من الحكمة، ويصح أن يكون من الحُكْم».", "mawaqif": [{"taliq": 5126, "mi": 0, "aya": 0, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 40", "qawl": "", "nass": "و {الحكيم} يصح أن يكون من الحكمة، ويصح أن يكون من الحكم", "qawaid": [], "tabi": ""}]}], "6": [{"id": 5127, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 41) عن قتادة قولًا آخر، فقال: «وقال قتادة: الشراء في هذه الآية مستعار، وإنما نزلت الآية في أحاديث قريش وتلهيهم بأمر الإسلام، وخوضهم في الأباطيل». ثم علّق عليه بقوله: «فكأن ترك ما يجب فعله وامتثال هذه المنكرات شراء لها، على حد قوله تعالى: {أُولئِكَ الَّذِينَ اشْتَرَوُا الضَّلالَةَ بِالهُدى} [البقرة: 16، 175]».", "mawaqif": [{"taliq": 5127, "mi": 0, "aya": 6, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 41", "qawl": "", "nass": "وقال قتادة: الشراء في هذه الآية مستعار، وإنما نزلت الآية في أحاديث قريش وتلهيهم بأمر الإسلام، وخوضهم في الأباطيل", "qawaid": [], "tabi": ""}]}, {"id": 5130, "kinds": "حصر", "text": "لم يذكر ابنُ جرير (18/ 539) غير قول ابن عباس.", "mawaqif": []}], "10": [{"id": 5132, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 43): «وقوله تعالى: {بِغَيْرِ عَمَدٍ تَرَوْنَها} يحتمل أن يعود الضمير على السَّماواتِ، فيكون المعنى: أن السماء بغير عمد، وأنها ترى كذلك. وهذا قول الحسن والناس، و {تَرَوْنَها} على هذا القول في موضع نصب على الحال. ويحتمل أن يعود الضمير على العمد؛ فيكون {تَرَوْنَها} صفة للعمد في موضع خفض، ويكون المعنى: أن السماء لها عمد لكن غير مرئية. قاله مجاهد، ونحا إليه ابن عباس. والمعنى الأول أصح، والجمهور عليه». ولم يذكر مستندًا، ثم قال: «ويجوز أن تكون {تَرَوْنَها} في موضع رفع على القطع، ولا عمد ثَمَّ».", "mawaqif": [{"taliq": 5132, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 43", "qawl": "", "nass": "وقوله تعالى: {بغير عمد ترونها} يحتمل أن يعود الضمير على السماوات، فيكون المعنى: أن السماء بغير عمد، وأنها ترى كذلك. وهذا قول الحسن والناس، و {ترونها} على هذا القول في موضع نصب على الحال. ويحتمل أن يعود الضمير على العمد؛ فيكون {ترونها} صفة للعمد في موضع خفض، ويكون المعنى: أن السماء لها عمد لكن غير مرئية. قاله مجاهد، ونحا إليه ابن عباس. والمعنى الأول أصح، والجمهور عليه", "qawaid": ["لم يذكر مستندًا"], "tabi": ""}]}, {"id": 5133, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 43): «وقوله تعالى: {كَرِيمٍ} يحتمل أن يريد مدحه من جهة إتقان صنعته، وظهور حسن الرتبة والتحكم للصنع فيها، فيعم حينئذ جميع الأنواع؛ لأن هذا المعنى في كلها. ويحتمل أن يريد مدحه بكرم جوهره، وحسن منظره، وما تقتضي له النفوس بأنه أفضل من سواه حتى يستحق الكرم؛ فتكون الأزواج على هذا مخصوصة في نفائس الأشياء ومستحسناتها، ولما كان عُظْمُ الموجودات كذلك خصص الحجة بها».", "mawaqif": [{"taliq": 5133, "mi": 0, "aya": 10, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 43", "qawl": "", "nass": "وقوله تعالى: {كريم} يحتمل أن يريد مدحه من جهة إتقان صنعته، وظهور حسن الرتبة والتحكم للصنع فيها، فيعم حينئذ جميع الأنواع؛ لأن هذا المعنى في كلها. ويحتمل أن يريد مدحه بكرم جوهره، وحسن منظره، وما تقتضي له النفوس بأنه أفضل من سواه حتى يستحق الكرم؛ فتكون الأزواج على هذا مخصوصة في نفائس الأشياء ومستحسناتها، ولما كان عظم الموجودات كذلك خصص الحجة بها", "qawaid": [], "tabi": ""}]}], "13": [{"id": 5134, "kinds": "ترجيح", "text": "قوّى ابنُ عطية (7/ 46) بهذا الأثر أن قوله تعالى: {إن الشرك لظلم عظيم} هو من قول الله تعالى، وليس من كلام لقمان عليه السلام، فقال: «وظاهر قوله: {إنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ} أنه من كلام لقمان، ويحتمل أن يكون خبرًا من الله تعالى منقطعًا من كلام لقمان، متصلًا به في تأكيد المعنى، ويؤيد هذا الحديث المأثور أنه لما نزلت: {ولَمْ يَلْبِسُوا إيمانَهُمْ بِظُلْمٍ} أشفق أصحاب رسول الله صلى الله عليه وسلم، وقالوا: أينا لم يظلم نفسه؟ فأنزل الله تعالى: {إنَّ الشِّرْكَ لَظُلْمٌ عَظِيمٌ} فسكن إشفاقهم. وإنما يسكن إشفاقهم بأن يكون ذلك خبرًا من الله تعالى، وقد يسكن الإشفاق بأن يذكر الله ذلك عن عبدٍ قد وصفه بالحكمة والسداد».", "mawaqif": [{"taliq": 5134, "mi": 0, "aya": 13, "alam": "ابن عطية", "fil": "قوى", "kind": "ترجيح", "ref": "7/ 46", "qawl": "", "nass": "وظاهر قوله: {إن الشرك لظلم عظيم} أنه من كلام لقمان، ويحتمل أن يكون خبرا من الله تعالى منقطعا من كلام لقمان، متصلا به في تأكيد المعنى، ويؤيد هذا الحديث المأثور أنه لما نزلت: {ولم يلبسوا إيمانهم بظلم} أشفق أصحاب رسول الله صلى الله عليه وسلم، وقالوا: أينا لم يظلم نفسه؟ فأنزل الله تعالى: {إن الشرك لظلم عظيم} فسكن إشفاقهم. وإنما يسكن إشفاقهم بأن يكون ذلك خبرا من الله تعالى، وقد يسكن الإشفاق بأن يذكر الله ذلك عن عبد قد وصفه بالحكمة والسداد", "qawaid": [], "tabi": ""}]}], "14": [{"id": 5135, "kinds": "نقد،نقل", "text": "قال ابنُ عطية (7/ 47): «{وهْنًا عَلى وهْنٍ} معناه: ضعفًا على ضعف. وقيل: إشارة إلى مشقة الحمل، ومشقة الولادة بعده. وقيل: إشارة إلى ضعف الولد، وضعف الأم معه. ويحتمل أنه أشار إلى تدرج حالها في زيادة الضعف، كأنه لم يُعَيِّن ضعفين، بل كأنه قال: حملته أمه، والضعف يتزيد بعد الضعف إلى أن ينقضي أمدُه».", "mawaqif": [{"taliq": 5135, "mi": 0, "aya": 14, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 47", "qawl": "", "nass": "{وهنا على وهن} معناه: ضعفا على ضعف. وقيل: إشارة إلى مشقة الحمل، ومشقة الولادة بعده. وقيل: إشارة إلى ضعف الولد، وضعف الأم معه. ويحتمل أنه أشار إلى تدرج حالها في زيادة الضعف، كأنه لم يعين ضعفين، بل كأنه قال: حملته أمه، والضعف يتزيد بعد الضعف إلى أن ينقضي أمده", "qawaid": [], "tabi": ""}]}], "16": [{"id": 5136, "kinds": "نقل", "text": "قال ابن عطية (7/ 49 - 50): «وقوله: {مِثْقالَ حَبَّةٍ} عبارة تصلح للجواهر، أي قدر حبة، وتصلح للأعمال، أي ما زنته على جهة المماثلة قدر حبة، فظاهر الآية أنه أراد شيئًا من الأشياء خفيًا قدر حبة، ويؤيد ذلك ما روي من أن ابن لقمان سأل أباه عن الحبة تقع في مثل البحر، أيعلمها الله؟ فراجعه لقمان بهذه الآية. وذكر كثير من المفسرين أنه أراد الأعمال المعاصي والطاعات، ويؤيد ذلك قوله: {يَأْتِ بِها اللَّهُ} أي: لا تفوت، وبهذا المعنى يتحصل في الموعظة ترجية وتخويف. فيضاف ذلك إلى تبيين قدرة الله تعالى، وفي القول الآخر ليس ترجية ولا تخويف. ومما يؤيد قول من قال: هي من الجواهر قراءة عبد الكريم الجزري» فتكِنّ «بكسر الكاف وشد النون من الكِنّ الذي هو الشيء المغطى، وقرأ جمهور القراء» إن تك «بالتاء من فوق،» مثقال «بالنصب على خبر» كان «، واسمها مضمر تقديره: مسألتك، على ما روي، أو المعصية أو الطاعة على القول الثاني».", "mawaqif": [{"taliq": 5136, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 49 - 50", "qawl": "", "nass": "وقوله: {مثقال حبة} عبارة تصلح للجواهر، أي قدر حبة، وتصلح للأعمال، أي ما زنته على جهة المماثلة قدر حبة، فظاهر الآية أنه أراد شيئا من الأشياء خفيا قدر حبة، ويؤيد ذلك ما روي من أن ابن لقمان سأل أباه عن الحبة تقع في مثل البحر، أيعلمها الله؟ فراجعه لقمان بهذه الآية. وذكر كثير من المفسرين أنه أراد الأعمال المعاصي والطاعات، ويؤيد ذلك قوله: {يأت بها الله} أي: لا تفوت، وبهذا المعنى يتحصل في الموعظة ترجية وتخويف. فيضاف ذلك إلى تبيين قدرة الله تعالى، وفي القول الآخر ليس ترجية ولا تخويف. ومما يؤيد قول من قال: هي من الجواهر قراءة عبد الكريم الجزري", "qawaid": [], "tabi": ""}]}, {"id": 5138, "kinds": "تعليق", "text": "علّق ابنُ كثير (11/ 55 - 56) على أثر ابن عباس، فقال: «وهذا -والله أعلم- كأنه مُتَلَقًّى من الإسرائيليات التي لا تُصَدَّق ولا تُكَذَّب. والظاهر -والله أعلم- أنّ المراد: أن هذه الحبة في حقارتها لو كانت داخل صخرة، فإن الله سيبديها ويظهرها بلطيف علمه».", "mawaqif": [{"taliq": 5138, "mi": 0, "aya": 16, "alam": "ابن كثير", "fil": "علق", "kind": "تعليق", "ref": "11/ 55 - 56", "qawl": "", "nass": "وهذا -والله أعلم- كأنه متلقى من الإسرائيليات التي لا تصدق ولا تكذب. والظاهر -والله أعلم- أن المراد: أن هذه الحبة في حقارتها لو كانت داخل صخرة، فإن الله سيبديها ويظهرها بلطيف علمه", "qawaid": [], "tabi": ""}]}, {"id": 5140, "kinds": "غيره", "text": "قال ابنُ عطية (7/ 51): «وقوله {يَأْتِ بِها اللَّهُ} إن أراد: الجواهر؛ فالمعنى: يأت بها إن احتيج إلى ذلك، إن كانت رزقًا ونحو هذا. وإن أراد: الأعمال؛ فمعناه: يأت بذكرها وحفظها ليجازي عليها بثواب أو عقاب».", "mawaqif": [{"taliq": 5140, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "قال", "kind": "قول", "ref": "7/ 51", "qawl": "", "nass": "وقوله {يأت بها الله} إن أراد: الجواهر؛ فالمعنى: يأت بها إن احتيج إلى ذلك، إن كانت رزقا ونحو هذا. وإن أراد: الأعمال؛ فمعناه: يأت بذكرها وحفظها ليجازي عليها بثواب أو عقاب", "qawaid": [], "tabi": ""}]}, {"id": 5141, "kinds": "نقد،نقل", "text": "أشار ابنُ عطية (7/ 50) إلى نحو ما جاء في قول يحيى بن سلّام وغيره، وانتقده فقال: «وقوله: {فَتَكُنْ فِي صَخْرَةٍ}، قيل: أراد: الصخرة التي عليها الأرض والحوت والماء، وهي على ظهر ملك. وقيل: هي صخرة في الريح. وهذا كله ضعيف لا يثبته سند، وإنما معنى الكلام المبالغة والانتهاء في التفهيم، أي: أن قدرته تنال ما يكون في تضاعيف صخرة، وما يكون في السماء وفي الأرض».", "mawaqif": [{"taliq": 5141, "mi": 0, "aya": 16, "alam": "ابن عطية", "fil": "أشار", "kind": "نقل", "ref": "7/ 50", "qawl": "يحيى بن", "nass": "وقوله: {فتكن في صخرة}، قيل: أراد: الصخرة التي عليها الأرض والحوت والماء، وهي على ظهر ملك. وقيل: هي صخرة في الريح. وهذا كله ضعيف لا يثبته سند، وإنما معنى الكلام المبالغة والانتهاء في التفهيم، أي: أن قدرته تنال ما يكون في تضاعيف صخرة، وما يكون في السماء وفي الأرض", "qawaid": [], "tabi": ""}]}], "18": [{"id": 5144, "kinds": "تعليق،نقل", "text": "ذكر ابنُ عطية (7/ 53) قول مجاهد، ثم علّق قائلًا: «وفي اللفظ الفخر بالنسب وغير ذلك».", "mawaqif": [{"taliq": 5144, "mi": 0, "aya": 18, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 53", "qawl": "مجاهد", "nass": "وفي اللفظ الفخر بالنسب وغير ذلك", "qawaid": [], "tabi": ""}]}], "20": [{"id": 5147, "kinds": "تعليق", "text": "علّق ابنُ جرير (18/ 566) على قراءتي الجمع والإفراد في قوله: {نعمه}، فقال: «والصواب من القول في ذلك عندنا أنهما قراءتان مشهورتان في قراء الأمصار متقاربتا المعنى، وذلك أن النعمة قد تكون بمعنى الواحدة، ومعنى الجماع، وقد يدخل في الجماع الواحدة. وقد قال -جل ثناؤه-: {وإن تعدوا نعمة الله لا تحصوها} [إبراهيم: 34، النحل: 18]، فمعلومٌ أنه لم يعنِ بذلك نعمة واحدة. وقال في موضع آخر: {ولم يك من المشركين * شاكرا لأنعمه} [النحل: 121] فجمعها، فبأي القراءتين قرأ القارئ ذلك فمصيب».", "mawaqif": [{"taliq": 5147, "mi": 0, "aya": 20, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "18/ 566", "qawl": "", "nass": "والصواب من القول في ذلك عندنا أنهما قراءتان مشهورتان في قراء الأمصار متقاربتا المعنى، وذلك أن النعمة قد تكون بمعنى الواحدة، ومعنى الجماع، وقد يدخل في الجماع الواحدة. وقد قال -جل ثناؤه-: {وإن تعدوا نعمة الله لا تحصوها} [إبراهيم: 34، النحل: 18]، فمعلوم أنه لم يعن بذلك نعمة واحدة. وقال في موضع آخر: {ولم يك من المشركين * شاكرا لأنعمه} [النحل: 121] فجمعها، فبأي القراءتين قرأ القارئ ذلك فمصيب", "qawaid": [], "tabi": ""}]}, {"id": 5148, "kinds": "ترجيح،بيان،نقل", "text": "ذكر ابنُ عطية (7/ 55) قراءة «نِعْمَةً» على الإفراد، ثم ذكر قول مجاهد على هذه القراءة أن المراد بها: لا إله إلا الله. وقول ابن عباس أنه فسرها بالإسلام، ثم رجّح أنها: «اسم جنس، كقوله تبارك وتعالى: {وإنْ تَعُدُّوا نِعْمَةَ اللَّهِ لا تُحْصُوها} [إبراهيم: 34، النحل: 18]».", "mawaqif": [{"taliq": 5148, "mi": 0, "aya": 20, "alam": "ابن عطية", "fil": "ذكر", "kind": "نقل", "ref": "7/ 55", "qawl": "", "nass": "نعمة", "qawaid": [], "tabi": ""}]}], "27": [{"id": 5149, "kinds": "تعليق", "text": "علَّق ابنُ جرير (18/ 574) على قراءة {والبَحْرُ يَمُدُّهُ} بالرفع، وقراءة النصب بقوله: «وبأيتهما قرأ القارئ فمصيب عندي».", "mawaqif": [{"taliq": 5149, "mi": 0, "aya": 27, "alam": "ابن جرير", "fil": "علق", "kind": "تعليق", "ref": "18/ 574", "qawl": "", "nass": "وبأيتهما قرأ القارئ فمصيب عندي", "qawaid": [], "tabi": ""}]}, {"id": 5151, "kinds": "تعليق،نقل", "text": "نقل ابنُ عطية (7/ 58) عن فرقة: أنها ذهبت: «إلى أن الكلمات هنا إشارة إلى المعلومات». ثم علَّق عليه بقوله: «وهذا قول ينحو إلى الاعتزال مِن حيث يرون أنه مخلوق».", "mawaqif": [{"taliq": 5151, "mi": 0, "aya": 27, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 58", "qawl": "", "nass": "إلى أن الكلمات هنا إشارة إلى المعلومات", "qawaid": [], "tabi": ""}]}], "32": [{"id": 5155, "kinds": "توجيه،بيان،نقل", "text": "نقل ابنُ عطية (7/ 61) عن مجاهد في معنى: {فَمِنهُمْ مُقْتَصِدٌ}، قال: «يريد: منهم مقتصد على كفره». ثم وجَّهه بقوله: «أي: مَن يسَلِّم لله تعالى، ويفهم نحو هذا من القدرة، وإن ضلَّ في الأصنام من جهة أنه يعظِّمها بسيرته ولسانه».\nووجَّه ابنُ كثير (11/ 80) تفسير مجاهد للمقتصد بالكافر بقوله: «كأنه فسر المقتصد ها هنا بالجاحد، كما قال تعالى: {فَلَمّا نَجّاهُمْ إلى البَرِّ إذا هُمْ يُشْرِكُونَ} [العنكبوت: 65]».", "mawaqif": [{"taliq": 5155, "mi": 0, "aya": 32, "alam": "ابن عطية", "fil": "نقل", "kind": "نقل", "ref": "7/ 61", "qawl": "", "nass": "يريد: منهم مقتصد على كفره", "qawaid": [], "tabi": ""}, {"taliq": 5155, "mi": 0, "aya": 32, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "11/ 80", "qawl": "", "nass": "كأنه فسر المقتصد ها هنا بالجاحد، كما قال تعالى: {فلما نجاهم إلى البر إذا هم يشركون} [العنكبوت: 65]", "qawaid": [], "tabi": ""}]}, {"id": 5156, "kinds": "توجيه،نقل", "text": "ذكر ابنُ جرير (18/ 580) في معنى قوله تعالى: {فَمِنهُمْ مُقْتَصِدٌ} أي: فمنهم مقتصد في قوله وإقراره بربِّه، وهو مع ذلك مُضْمِرٌ الكفر به. وأدرج تحت هذا المعنى أثر مجاهد، وابن زيد.\nوحمل ابنُ كثير (11/ 80) كلام ابن زيد في معنى: {فَمِنهُمْ مُقْتَصِدٌ} على أنه في المؤمن، فقال: «هو المتوسط في العمل». ثم وجَّهه بقوله: «وهذا الذي قاله ابن زيد هو المراد في قوله: {فَمِنهُمْ ظالِمٌ لِنَفْسِهِ ومِنهُمْ مُقْتَصِدٌ ومِنهُمْ سابِقٌ بِالخَيْراتِ} [فاطر: 32]، فالمقتصد هاهنا هو: المتوسط في العمل. ويحتمل أن يكون مرادًا هنا أيضًا، ويكون من باب الإنكار على من شاهد تلك الأهوال والأمور العظام والآيات الباهرات في البحر، ثم بعد ما أنعم الله عليه من الخلاص، كان ينبغي أن يقابل ذلك بالعمل التام، والدؤوب في العبادة، والمبادرة إلى الخيرات، فمن اقتصد بعد ذلك كان مقصرًا والحالة هذه».", "mawaqif": [{"taliq": 5156, "mi": 0, "aya": 32, "alam": "ابن جرير", "fil": "ذكر", "kind": "نقل", "ref": "18/ 580", "qawl": "", "nass": "", "qawaid": [], "tabi": ""}, {"taliq": 5156, "mi": 0, "aya": 32, "alam": "ابن كثير", "fil": "حمل", "kind": "توجيه", "ref": "11/ 80", "qawl": "", "nass": "هو المتوسط في العمل", "qawaid": [], "tabi": ""}]}], "33": [{"id": 5157, "kinds": "توجيه", "text": "وجَّه ابنُ كثير (11/ 81) قول ابن عباس وما في معناه من أن {الغرور}: الشيطان بقوله: «فإنه يغر ابن آدم ويَعِدُه ويمنيه، وليس من ذلك شيء، بل كما قال تعالى: {يَعِدُهُمْ ويُمَنِّيهِمْ وما يَعِدُهُمُ الشَّيْطانُ إلا غُرُورًا} [النساء: 120]».", "mawaqif": [{"taliq": 5157, "mi": 0, "aya": 33, "alam": "ابن كثير", "fil": "وجه", "kind": "توجيه", "ref": "11/ 81", "qawl": "ابن عباس", "nass": "فإنه يغر ابن آدم ويعده ويمنيه، وليس من ذلك شيء، بل كما قال تعالى: {يعدهم ويمنيهم وما يعدهم الشيطان إلا غرورا} [النساء: 120]", "qawaid": [], "tabi": ""}]}], "34": [{"id": 5158, "kinds": "نقد،نقل", "text": "ذكر ابن كثير (11/ 84) هذا الحديث بألفاظ متقاربة، وذكر أنه من رواية الإمام أحمد بسنده عن أبي النضر، عن عبدالحميد، عن شهر، عن عبد الله بن عباس مرفوعًا، ثم انتقده قائلًا: «حديث غريب، ولم يخرجوه».", "mawaqif": [{"taliq": 5158, "mi": 0, "aya": 34, "alam": "ابن كثير", "fil": "ذكر", "kind": "نقل", "ref": "11/ 84", "qawl": "", "nass": "حديث غريب، ولم يخرجوه", "qawaid": [], "tabi": ""}]}]}, "athar": {"60930": {"num": 60930, "aya": 12, "qail": "ابن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن ابن عباس، قال: قال رسول الله صلى الله عليه وسلم: «اتخذوا السودان؛ فإن ثلاثة منهم سادات أهل الجنة: لقمان الحكيم، والنجاشي، وبلال المؤذن»."}, "61058": {"num": 61058, "aya": 19, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {واغْضُضْ مِن صَوْتِكَ}، قال: أمره بالاقتصاد في صوته."}, "61060": {"num": 61060, "aya": 19, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- {واغْضُضْ مِن صَوْتِكَ"}, "61062": {"num": 61062, "aya": 19, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر، في قوله: {إنَّ أنْكَرَ الأَصْواتِ لَصَوْتُ الحَمِيرِ}، قال: أنكرها على السمع."}, "61063": {"num": 61063, "aya": 19, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق أبان بن تغلب- في قوله: {إن أنكر الأصوات لصوت الحمير}، قال: {أنكر}: أقبح."}, "60936": {"num": 60936, "aya": 12, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس، قال: كان لقمانُ عبدًا أسود."}, "60937": {"num": 60937, "aya": 12, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عبد الله بن عباس -من طريق عكرمة- قال: كان لقمان عبدًا حبشيًّا نجارًا."}, "61069": {"num": 61069, "aya": 19, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {إنَّ أنْكَرَ الأَصْواتِ} قال: أقبح الأصوات {لَصَوْتُ الحَمِيرِ} قال: أوله زفير وآخره شهيق."}, "61197": {"num": 61197, "aya": 34, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "نزول الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قال: جاء رجلٌ مِن أهل البادية، فقال: إنّ امرأتي حُبلى؛ فأخبرني ما تلد؟ وبلادنا مُجدبة؛ فأخبرني متى ينزل الغيث؟ وقد علمتُ متى وُلدت؛ فأخبرني متى أموت؟ فأنزل الله: {إنَّ اللَّهَ عِنْدَهُ عِلْمُ السّاعَةِ}."}, "60943": {"num": 60943, "aya": 12, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد بن جبر -من طريق سعيد الزبيدي- قال: كان لقمان الحكيم عبدًا حبشيًّا، غليظ الشفتين، مصفح القدمين، قاضيًا لبني إسرائيل."}, "60944": {"num": 60944, "aya": 12, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن مجاهد بن جبر-من طريق الحكم- قال: كان لقمان رجلًا صالحًا، ولم يكن نبيًّا."}, "61202": {"num": 61202, "aya": 34, "qail": "عبد الله بن عمر", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عمر، أن رسول الله صلى الله عليه وسلم قال: «مفاتح الغيب خمسة». ثم قرأ هؤلاء الآيات: {إنَّ اللَّهَ عِنْدَهُ عِلْمُ السّاعَةِ} إلى آخرها."}, "60947": {"num": 60947, "aya": 12, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن قتادة بن دعامة -من طريق سعيد بن بشير- قال: كان لقمان رجلًا أفطس، مِن أرض الحبشة."}, "60948": {"num": 60948, "aya": 12, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن قتادة بن دعامة، قال: خيّر الله تعالى لقمان بين الحكمة والنبوة، فاختار الحكمة على النبوة، فأتاه جبريل وهو نائم، فذرَّ عليه الحكمة، فأصبح ينطق بها، فقيل له: كيف اخترت الحكمة على النبوة، وقد خيّرك ربك؟ فقال: إنه لو أرسل إليَّ بالنبوة عزمة لرجوت فيها الفوز منه، ولكنت أرجو أن أقوم بها، ولكنه خيّرني فخفتُ أن أضعف عن النبوة، فكانت الحكمة أحب إليَّ."}, "61076": {"num": 61076, "aya": 19, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "آثار متعلقة بالآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- قال: لو كان رفعُ الصوت خيرًا ما جعله الله للحمير."}, "61210": {"num": 61210, "aya": 34, "qail": "عمرو بن شعيب", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن عمرو بن شعيب، أن رجلًا قال: يا رسول الله، هل مِن العلم عِلْمٌ لم تُؤْتَهُ؟ قال: «لقد أوتيتُ علمًا كثيرًا، وعلمًا حسنًا». أو كما قال رسول الله صلى الله عليه وسلم، ثم تلا رسول الله صلى الله عليه وسلم هذه الآية: «{إنَّ اللَّهَ عِنْدَهُ عِلْمُ السّاعَةِ ويُنَزِّلُ الغَيْثَ ويَعْلَمُ ما فِي الأَرْحامِ وما تَدْرِي نَفْسٌ ماذا تَكْسِبُ غَدًا وما تَدْرِي نَفْسٌ بِأَيِّ أرْضٍ تَمُوتُ إنَّ اللَّهَ عَلِيمٌ خَبِيرٌ} لا يعلمهن إلا الله تبارك وتعالى»."}, "61211": {"num": 61211, "aya": 34, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {إنَّ اللَّهَ عِنْدَهُ عِلْمُ السّاعَةِ} قال: خمس من الغيب استأثر الله بهن، فلم يُطلِع عليهنَّ ملكا مقرّبًا، ولا نبيًّا مرسلًا: {إنَّ اللَّهَ عِنْدَهُ عِلْمُ السّاعَةِ} ولا يدري أحد من الناس متى تقوم الساعة، في أي سنة ولا في أي شهر؛ أليلًا أم نهارًا، {ويُنَزِّلُ الغَيْثَ} فلا يعلم أحد متى ينزل الغيث؛ أليلًا أم نهارًا، {ويَعْلَمُ ما فِي الأَرْحامِ} فلا يعلم أحد ما في الأرحام؛ أذكر أم أنثى، أحمر أو أسود، {وما تَدْرِي نَفْسٌ ماذا تَكْسِبُ غَدًا} أخير أم شر، {وما تَدْرِي نَفْسٌ بِأَيِّ أرْضٍ تَمُوتُ} ليس أحد مِن الناس يدري أين مضجعه من الأرض؛ أفي بحر أم في بر، في سهل أم في جبل؟."}, "61214": {"num": 61214, "aya": 34, "qail": "ابن عمر", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن ابن عمر، قال: قال رسول الله صلى الله عليه وسلم: «مفاتيح الغيب خمس لا يعلمهن إلا الله: لا يعلم ما في غدٍ إلا الله، ولا متى تقوم الساعة إلا الله، ولا يعلم ما في الأرحام إلا الله، ولا متى ينزل الغيث إلا الله، وما تدري نفس بأي أرض تموت إلا الله»."}, "60963": {"num": 60963, "aya": 14, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {وهْنًا عَلى وهْنٍ}، قال: شِدَّة بعد شدة، وخَلْقًا بعد خَلْق."}, "60837": {"num": 60837, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق أبي فاختة- قال: نزلت هذه الآية في رجلٍ اشترى جارية تُغَنِّيه ليلًا ونهارًا."}, "60838": {"num": 60838, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس، في قوله: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، قال: أُنزلت في النضر بن الحارث، اشترى قينة، فكان لا يسمع بأحد يريد الإسلام إلا انطلق به إلى قينته، فيقول: أطعميه، واسقيه، وغنِّيه، هذا خيرٌ مِمّا يدعوك إليه محمد مِن الصلاة، والصيام، وأن تقاتل بين يديه. فنزلت."}, "60839": {"num": 60839, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "نزول الآية", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ} قال: باطل الحديث، وهو الغناء ونحوه، {لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ} قال: قراءة القرآن، وذِكر الله. نزلت في رجل من قريش اشترى جارية مغنية."}, "61222": {"num": 61222, "aya": 34, "qail": "عائشة", "tabaqa": "صحابي", "bab": "آثار متعلقة بالآية", "text": "عن عائشة -من طريق مسروق- قالت: مَن حدَّثك أنّه يعلم ما في غدٍ فقد كذب. ثم قرأت: {وما تَدْرِي نَفْسٌ ماذا تَكْسِبُ غَدًا}."}, "60969": {"num": 60969, "aya": 14, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- {حَمَلَتْهُ أُمُّهُ وهْنًا عَلى وهْنٍ}: أي: جَهْدًا على جَهْد."}, "60849": {"num": 60849, "aya": 6, "qail": "أبي الصهباء", "tabaqa": "", "bab": "تفسير الآية", "text": "عن أبي الصهباء، قال: سألتُ عبد الله بن مسعود عن قوله تعالى: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}. قال: فقال: الغناء، والذي لا إله إلا هو. يُرَدّدها ثلاث مرات."}, "60850": {"num": 60850, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق سعيد بن جبير- {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، قال: الغناء."}, "60851": {"num": 60851, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق مقسم- قال: هو الغناء، والاستماع له، يعني قوله: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}."}, "60852": {"num": 60852, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق أبي صالح- في قوله: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}: يعني: باطل الحديث، وهو النضر بن الحارث بن علقمة، اشترى أحاديث الأعاجم وصنيعهم في دهرهم، وكان يكتب الكتب مِن الحيرة والشام ويُكَذِّب بالقرآن، فأعرض عنه فلم يؤمن به."}, "60853": {"num": 60853, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، قال: باطل الحديث، وهو الغناء ونحوه."}, "60854": {"num": 60854, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق سعيدبن جبير- {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، قال: هو الغناء، وأشباهه."}, "60855": {"num": 60855, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن عبد الله بن عباس -من طريق مجاهد- {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، قال: هو شراء المُغَنِّية."}, "60856": {"num": 60856, "aya": 6, "qail": "جابر بن عبد الله", "tabaqa": "صحابي", "bab": "تفسير الآية", "text": "عن جابر بن عبد الله -من طريق أبي ظبيان- {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، قال: هو الغناء، والاستماع له."}, "60858": {"num": 60858, "aya": 6, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "قال مجاهد بن جبر: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، يعني: شِراء القِيان والمُغَنِّين."}, "60859": {"num": 60859, "aya": 6, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح - في قوله: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، قال: هو اشتراؤه المغني والمغنية بالمال الكثير، والاستماع إليه وإلى مثله مِن الباطل."}, "60860": {"num": 60860, "aya": 6, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق عبد الكريم- {ومِن النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، قال: هو الغناء، وكل لعبٍ لهو."}, "60861": {"num": 60861, "aya": 6, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ليث- في قوله: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، قال: هو الغناء، أو الغناء منه، أو الاستماع له."}, "60862": {"num": 60862, "aya": 6, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن مجاهد بن جبر -من طريق ابن جريج- قال: اللهو: الطبل."}, "60992": {"num": 60992, "aya": 16, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {إنها إنْ تَكُ مِثْقالَ حَبَّةٍ مِن خَرْدَلٍ}، قال: مِن خير أو شر."}, "60865": {"num": 60865, "aya": 6, "qail": "شعيب بن يسار", "tabaqa": "", "bab": "تفسير الآية", "text": "عن شعيب بن يسار، قال: سألتُ عكرمة عن لهو الحديث. قال: هو الغناء."}, "60998": {"num": 60998, "aya": 16, "qail": "عبد الله بن الحارث", "tabaqa": "", "bab": "", "text": "عن عبد الله بن الحارث - من طريق المنهال-، قال: الصخرة خضراء على ظهر حوت."}, "60872": {"num": 60872, "aya": 6, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْو الحَدِيثِ}، قال: شراؤه: استحبابه، وبحسب المرء مِن الضلالة أن يختار حديثَ الباطل على حديث الحق."}, "60873": {"num": 60873, "aya": 6, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "تفسير الآية", "text": "قال قتادة بن دعامة: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ} هو كل لهو ولعب."}, "61000": {"num": 61000, "aya": 16, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {فَتَكُنْ فِي صَخْرَةٍ}، قال: في جبل."}, "60875": {"num": 60875, "aya": 6, "qail": "مطر الوراق", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن مطر الوراق -من طريق ابن شوذب- {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ}، قال: اشتراؤه: استحبابه."}, "60879": {"num": 60879, "aya": 6, "qail": "عبد الرحمن بن زيد بن أسلم", "tabaqa": "تابع التابعين", "bab": "تفسير الآية", "text": "عن عبد الرحمن بن زيد بن أسلم -من طريق ابن وهب- في قوله: {ومِنَ النّاسِ مَن يَشْتَرِي لَهْوَ الحَدِيثِ لِيُضِلَّ عَنْ سَبِيلِ اللَّه بِغَيْرِ عِلْمٍ ويَتَّخِذَها هُزُوًا}، قال: هؤلاء أهل الكفر، ألا ترى إلى قوله: {وإذا تُتْلى عَلَيْهِ آياتُنا ولّى مُسْتَكْبِرًا كَأَنْ لَمْ يَسْمَعْها كَأَنَّ فِي أُذُنَيْهِ وقْرًا} فليس هكذا أهل الإسلام. قال: وناس يقولون: هي فيكم. وليس كذلك. قال: وهو الحديث الباطل الذي كانوا يَلْغون فيه."}, "61007": {"num": 61007, "aya": 16, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {إنَّ اللَّهَ لَطِيفٌ} قال: باستخراجها، {خَبِير} قال: بمستقرها."}, "60881": {"num": 60881, "aya": 6, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس -من طريق عطية العوفي- في قوله: {لِيُضِلَّ عَنْ سَبِيلِ اللَّهِ}، قال: قراءة القرآن، وذِكر الله."}, "60882": {"num": 60882, "aya": 6, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ويَتَّخِذَها هُزُوًا}، قال: سبيل الله، يتخذ السبيل هزوًا."}, "60883": {"num": 60883, "aya": 6, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {ويَتَّخِذَها هُزُوًا}، قال: يستهزئ بها ويكذِّب بها."}, "60884": {"num": 60884, "aya": 6, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "قال قتادة بن دعامة: {ويَتَّخِذَها هُزُوًا} استحبوا الضلالة على الهدى."}, "60890": {"num": 60890, "aya": 6, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "آثار متعلقة بالآية", "text": "عن قتادة بن دعامة -من طريق سعيد- قال: بحسب المرء مِن الضلالة أن يختار حديثَ الباطل على حديث الحق، وما يضُرُّ على ما ينفع."}, "61052": {"num": 61052, "aya": 19, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق جابر- في قوله: {واقْصِدْ فِي مَشْيِكَ}، قال: تَواضَعْ."}, "61053": {"num": 61053, "aya": 19, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {واقْصِدْ فِي مَشْيِكَ}، قال: نهاه عن الخُيَلاء."}, "61030": {"num": 61030, "aya": 18, "qail": "إبراهيم النخعي", "tabaqa": "تابعي", "bab": "", "text": "عن إبراهيم النخعي -من طريق مغيرة، ومنصور- قال: {ولا تُصَعِّرْ خَدَّكَ لِلنّاسِ} هو التَّشْدِيق."}, "61032": {"num": 61032, "aya": 18, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ولا تُصَعِّرْ خَدَّكَ لِلنّاسِ}، قال: الصدود والإعراض بالوجه عن الناس."}, "61033": {"num": 61033, "aya": 18, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق منصور- {ولا تُصَعِّرْ خَدَّكَ لِلنّاسِ}، قال: الرجلُ يكونُ بينه وبين أخيه الحِنَة، فيراه، فيُعرض عنه."}, "61054": {"num": 61054, "aya": 19, "qail": "يزيد بن أبي حبيب", "tabaqa": "تابعي", "bab": "", "text": "عن يزيد بن أبي حبيب -من طريق عبد الله بن عقبة- في قوله: {واقصد في مشيك}، قال: مِن السُّرْعة."}, "61046": {"num": 61046, "aya": 18, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- {كُلَّ مُخْتالٍ} قال: مُتَكَبِّر، {فَخُورٍ} يُعَدِّد ما أعطى الله، وهو لا يشكر الله."}, "60921": {"num": 60921, "aya": 12, "qail": "عبد الله بن عباس", "tabaqa": "صحابي", "bab": "", "text": "عن عبد الله بن عباس، في قوله: {ولَقَدْ آتَيْنا لُقْمانَ الحِكْمَةَ}، قال: يعني: العقل، والفهم، والفِطنة، في غير نُبُوَّة."}, "60922": {"num": 60922, "aya": 12, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق يونس- في قوله: {ولَقَدْ آتَيْنا لُقْمانَ الحِكْمَةَ}، قال: الحكمة: الصواب."}, "60923": {"num": 60923, "aya": 12, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق سفيان، عن رجل- {ولَقَدْ آتَيْنا لُقْمانَ الحِكْمَةَ}، قال: القرآن."}, "60924": {"num": 60924, "aya": 12, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- قال: الحكمة: الأمانة."}, "60925": {"num": 60925, "aya": 12, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن أبي نجيح- في قوله: {ولَقَدْ آتَيْنا لُقْمانَ الحِكْمَةَ}، قال: العقل، والفقه، والإصابة في القول، في غير نبوة."}, "60926": {"num": 60926, "aya": 12, "qail": "مجاهد بن جبر", "tabaqa": "تابعي", "bab": "", "text": "عن مجاهد بن جبر -من طريق ابن جريج- في قوله: {ولقد ءاتينا لقمان الحكمة}، قال: الفقه، والعلم، والإصابة في غير نبوة. {ومن يؤت الحكمة فقد أوتي خيرًا كثيرًا} [البقرة: 269]، قال: الإصابة."}, "60927": {"num": 60927, "aya": 12, "qail": "قتادة بن دعامة", "tabaqa": "تابعي", "bab": "", "text": "عن قتادة بن دعامة -من طريق سعيد- في قوله: {ولَقَدْ آتَيْنا لُقْمانَ الحِكْمَةَ}، قال: الفقه في الإسلام، ولم يكن نبيًّا، ولم يُوحَ إليه."}}, "n_athar": {"0": 13, "3": 2, "4": 2, "5": 2, "6": 59, "7": 6, "8": 3, "10": 13, "11": 7, "12": 33, "13": 7, "14": 15, "15": 16, "16": 19, "17": 14, "18": 26, "19": 26, "20": 26, "21": 2, "22": 7, "23": 3, "24": 2, "25": 2, "26": 2, "27": 16, "28": 6, "29": 6, "30": 2, "31": 8, "32": 24, "33": 14, "34": 26}, "muh": ["ابن جرير", "ابن عطية", "ابن كثير", "ابن تيمية", "ابن القيم"], "ords": ["الأول", "الثاني", "الثالث", "الرابع", "الخامس", "السادس", "السابع", "الثامن", "التاسع", "العاشر"], "index": "فهرس.html"});